 const wristToElbow=point('ℓCE','الطول من الرسغ إلى المرفق','Wrist-to-elbow length','قِس من نقطة C عند الرسغ إلى نقطة E عند المرفق، وفق سهم الطول في رسم الذراع.','Measure from wrist point C to elbow point E, following the arm diagram’s length marker.');
 const underBust=point('cU','محيط أسفل الثدي','Underbust circumference','مرّر الشريط أفقيًا حول الجذع أسفل الثدي مباشرة عند U، دون شدّه.','Place the tape level around the torso directly below the breasts at U, without tightening it.');
 const upperHip=point('cH','محيط أعلى الحوض','Upper-hip circumference','لف الشريط أفقيًا حول أعلى الحوض عند خط H أسفل الخصر. في هذا الموديل H غير خط الأرداف K.','Measure level around the upper hips at H below the waist. For this model, H is separate from buttock level K.');
