 const vestChest=point('cN','محيط الصدر تحت الإبطين','Chest circumference below the armpits','لف الشريط أفقيًا حول الصدر من تحت الإبطين عند خط N، حسب رسم السترة.','Measure level around the chest directly below the armpits at N on the vest diagram.');
 const armhole=point('cH','محيط فتحة الذراع','Armhole circumference','مرّر الشريط من أعلى الكتف إلى تحت الإبط ثم أعده لنقطة البداية، على مسار H في الرسم.','Run the tape from the shoulder down under the armpit and back to the starting point along the illustrated H loop.');
